import{_ as a,o as e,c as i,ac as l}from"./chunks/framework.Bzw8ikz_.js";const b=JSON.parse('{"title":"Vite 为什么快","description":"","frontmatter":{},"headers":[],"relativePath":"front/build-tools/vite/vite8.md","filePath":"front/build-tools/vite/vite8.md","lastUpdated":1783951542000}'),o={name:"front/build-tools/vite/vite8.md"};function r(d,t,h,n,s,c){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="vite-为什么快" tabindex="-1">Vite 为什么快 <a class="header-anchor" href="#vite-为什么快" aria-label="Permalink to &quot;Vite 为什么快&quot;">​</a></h1><p>可以简单从以下几个角度回答：</p><ol><li><strong>开发阶段利用原生 ESM 按需加载</strong></li></ol><p>不像传统 bundler 那样先把整个应用完整打包后再启动，Vite 会在浏览器请求模块时再处理对应模块。</p><ol start="2"><li><strong>热更新粒度更细</strong></li></ol><p>改了哪个模块，就尽量只更新哪个模块，而不是让整个应用重新构建。</p><ol start="3"><li><strong>开发和生产的职责划分更清晰</strong></li></ol><p>开发阶段重点优化“反馈速度”，生产阶段重点优化“产物质量”。</p><h2 id="开发环境和生产环境的目标不一样。" tabindex="-1">开发环境和生产环境的目标不一样。 <a class="header-anchor" href="#开发环境和生产环境的目标不一样。" aria-label="Permalink to &quot;开发环境和生产环境的目标不一样。&quot;">​</a></h2><ol><li><p>开发环境的目标</p><ul><li>快速启动</li><li>快速反馈</li><li>方便调试</li></ul></li><li><p>生产环境的目标</p><ul><li>更少请求</li><li>更小体积</li><li>更好缓存</li><li>更高加载性能</li><li>更稳定的部署产物</li></ul></li></ol><p>在 Vite 2 到 Vite 7 的长期演进中，Vite 依赖的是一套双引擎思路。</p><table tabindex="0"><thead><tr><th>场景</th><th>主要工具</th><th>语言</th><th>作用特点</th></tr></thead><tbody><tr><td>开发阶段的快速处理</td><td>esbuild</td><td>Go</td><td>很快，但能力边界相对明确</td></tr><tr><td>生产阶段的正式构建</td><td>Rollup</td><td>JavaScript</td><td>生态成熟、插件能力强</td></tr></tbody></table><h1 id="vite8新特性" tabindex="-1">vite8新特性 <a class="header-anchor" href="#vite8新特性" aria-label="Permalink to &quot;vite8新特性&quot;">​</a></h1><h1 id="vite8-基础配置" tabindex="-1">vite8 基础配置 <a class="header-anchor" href="#vite8-基础配置" aria-label="Permalink to &quot;vite8 基础配置&quot;">​</a></h1><h1 id="ts与框架集成" tabindex="-1">TS与框架集成 <a class="header-anchor" href="#ts与框架集成" aria-label="Permalink to &quot;TS与框架集成&quot;">​</a></h1><h2 id="依赖预构建" tabindex="-1">依赖预构建 <a class="header-anchor" href="#依赖预构建" aria-label="Permalink to &quot;依赖预构建&quot;">​</a></h2><h1 id="css工程化" tabindex="-1">css工程化 <a class="header-anchor" href="#css工程化" aria-label="Permalink to &quot;css工程化&quot;">​</a></h1><h1 id="hmr-hot-module-repalcement-热模块替换" tabindex="-1">HMR（Hot Module Repalcement）热模块替换 <a class="header-anchor" href="#hmr-hot-module-repalcement-热模块替换" aria-label="Permalink to &quot;HMR（Hot Module Repalcement）热模块替换&quot;">​</a></h1><h1 id="vite插件" tabindex="-1">vite插件 <a class="header-anchor" href="#vite插件" aria-label="Permalink to &quot;vite插件&quot;">​</a></h1><h1 id="代码分割" tabindex="-1">代码分割 <a class="header-anchor" href="#代码分割" aria-label="Permalink to &quot;代码分割&quot;">​</a></h1><h1 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h1>',21)])])}const p=a(o,[["render",r]]);export{b as __pageData,p as default};
